function flow(action,parameters,respond,effect,initial=signed){
 let context=clone(initial),argumentsValue={feature:Object.keys(manifest.features).find(feature=>manifest.features[feature].includes(action)),action,parameters:clone(parameters)},result=clone(plugin['feature.invoke'](argumentsValue,context)),requests=[],effects=[],hops=0;
 for(let count=0;count<30;count++){
  assert.equal(result.error,undefined,'Flow '+action+' error '+JSON.stringify(result));
  if(result.request){assert(hops++<4,'Flow segment must retain HTTP bound');requests.push(result.request);const response=respond(result.request,result.state,requests.length-1);result=clone(plugin.onResponse('feature.invoke',clone(response),clone(result.state),context));continue;}
  context.storage=clone(result.storage||context.storage);
  if(result.result?.hostEffect){effects.push(result.result.hostEffect);const reply=result.result.hostEffect.type==='source.continue'?null:effect(result.result.hostEffect,effects.length-1);argumentsValue={feature:argumentsValue.feature,action,parameters:{...clone(parameters),$continuation:{state:result.result.continuation,effect:reply?.ok===false?reply:{ok:true,result:reply},token:'host-bound-token'}}};context.secureRandomBase64=Buffer.alloc(256,effects.length+1).toString('base64');result=clone(plugin['feature.invoke'](argumentsValue,context));hops=0;continue;}
  return {result:result.result,storage:context.storage,requests,effects};
 }
 assert.fail('Unbounded feature flow');
}
