function continuedCore(operation,parameters,respond,initial=entropy,effect=()=>assert.fail('Unexpected core effect')){let context=clone(initial),result=clone(plugin[operation](clone(parameters),context)),requests=[],segments=0,hops=0;for(let i=0;i<40;i++){assert.equal(result.error,undefined);if(result.request){assert(hops++<4);requests.push(result.request);result=clone(plugin.onResponse(operation,{status:200,body:JSON.stringify(respond(result.request,requests.length-1))},clone(result.state),context));continue;}context.storage=clone(result.storage);if(result.result?.hostEffect){const reply=result.result.hostEffect.type==='source.continue'?null:effect(result.result.hostEffect);segments++;result=clone(plugin[operation]({...clone(parameters),$continuation:{state:result.result.continuation,effect:{ok:true,result:reply},token:'host-bound-token'}},context));hops=0;continue;}return {result:result.result,storage:context.storage,requests,segments};}assert.fail('Unbounded core continuation');}
