for(const pending of corePending.toReversed()){const reference=pending.parameters.id,proof={checkToken:'body-'+reference,headerAntiCheatToken:'header-'+reference};let resumed=clone(plugin['collection.save']({type:'playlist',id:'999',saved:!pending.parameters.saved,$continuation:{state:pending.envelope.continuation,effect:{ok:true,result:proof},token:'owned-core-token'}},clone(concurrentContext)));assert.equal(resumed.error,undefined);assert(new URL(resumed.request.url).pathname.endsWith(pending.parameters.saved?'/playlist/subscribe':'/playlist/unsubscribe'));assert.equal(JSON.parse(resumed.request.body).id,reference);assert.equal(JSON.parse(resumed.request.body).checkToken,'body-'+reference);assert.equal(resumed.request.headers['X-antiCheatToken'],'header-'+reference);resumed=clone(plugin.onResponse('collection.save',{status:200,body:'{"code":200}'},resumed.state,clone(concurrentContext)));assert.equal(resumed.result,true);concurrentContext.storage=clone(resumed.storage);}
assert(!Object.keys(concurrentContext.storage).some(key=>key.startsWith('pending:core:collection.save:')));
// The same key isolation applies to two uploads waiting for the same picker action.
const uploadContext=clone(entropy),uploadPending=[];
for(const songName of ['Upload A','Upload B']){const first=clone(plugin['feature.invoke']({feature:'cloud',action:'uploadCloudSong',parameters:{song:songName}},clone(uploadContext)));assert.equal(first.result.hostEffect.type,'files.pick');uploadPending.push({songName,envelope:first.result});uploadContext.storage=clone(first.storage);}
assert.notEqual(uploadPending[0].envelope.continuation.key,uploadPending[1].envelope.continuation.key);
for(const [index,pending]of uploadPending.toReversed().entries()){const handle='owned-file-'+index,file={handle,fileName:'recording-'+index+'.mp3',size:10,md5:'a'.repeat(32)},parameters={feature:'cloud',action:'uploadCloudSong',parameters:{$continuation:{state:pending.envelope.continuation,effect:{ok:true,result:file},token:'owned-upload-token'}}};let result=clone(plugin['feature.invoke'](parameters,clone(uploadContext)));assert.equal(result.state.file.song,pending.songName);assert.equal(result.state.file.handle,handle);for(let step=0;result.request;step++){const path=new URL(result.request.url).pathname,body=path.endsWith('/upload/check')?{code:200,needUpload:false,songId:400+index}:path.endsWith('/nos/token/alloc')?{code:200,result:{resourceId:'resource-'+index}}:path.endsWith('/upload/cloud/info/v2')?{code:200,songId:400+index}:{code:200};if(path.endsWith('/upload/cloud/info/v2'))assert.equal(JSON.parse(result.request.body).song,pending.songName);result=clone(plugin.onResponse('feature.invoke',{status:200,body:JSON.stringify(body)},result.state,clone(uploadContext)));assert.equal(result.error,undefined);assert(step<4);}assert.equal(result.result.status,'completed');assert.equal(result.result.songId,String(400+index));uploadContext.storage=clone(result.storage);}
assert(!Object.keys(uploadContext.storage).some(key=>key.startsWith('pending:cloud:uploadCloudSong:')));
const malformedPlan=clone(plugin['collection.save']({type:'playlist',id:'11',saved:true,$continuation:{state:{key:corePending[0].envelope.continuation.key+'x',nonce:corePending[0].envelope.continuation.nonce},effect:{ok:true,result:security}}},clone(concurrentContext)));assert.equal(malformedPlan.error,'INVALID_RESPONSE');
const capacityContext=clone(entropy);for(let index=0;index<16;index++){const pending=clone(plugin['feature.invoke']({feature:'login',action:'webLogin',parameters:{}},clone(capacityContext)));assert.equal(pending.error,undefined);capacityContext.storage=clone(pending.storage);}const activeKeys=Object.keys(capacityContext.storage).filter(key=>key.startsWith('pending:'));assert.equal(activeKeys.length,16);const deniedPlan=clone(plugin['feature.invoke']({feature:'login',action:'webLogin',parameters:{}},clone(capacityContext)));assert.equal(deniedPlan.error,'UNAVAILABLE');assert.deepEqual(Object.keys(capacityContext.storage).filter(key=>key.startsWith('pending:')),activeKeys);const expired=JSON.parse(capacityContext.storage[activeKeys[0]]);expired.expiresAt=0;capacityContext.storage[activeKeys[0]]=JSON.stringify(expired);const reclaimed=clone(plugin['feature.invoke']({feature:'login',action:'webLogin',parameters:{}},clone(capacityContext)));assert.equal(reclaimed.error,undefined);assert.equal(Object.keys(reclaimed.storage).filter(key=>key.startsWith('pending:')).length,16);assert.equal(reclaimed.storage[activeKeys[0]],undefined);assert(activeKeys.slice(1).every(key=>reclaimed.storage[key]===capacityContext.storage[key]));
const replayedCore=clone(plugin['collection.save']({...corePending[0].parameters,$continuation:{state:corePending[0].envelope.continuation,effect:{ok:true,result:security},token:'replayed-token'}},clone(concurrentContext)));assert.equal(replayedCore.error,'INVALID_RESPONSE');assert.equal(replayedCore.request,undefined);
// Follow status is tri-state until a matching artist response supplies an explicit boolean.
for(const followed of [true,false]){const explicit=drive('collection.saved',{type:'artist',id:'42'},[profile,{code:200,artist:{id:42,followed}}]);assert.equal(explicit.result.result,followed);assert.equal(explicit.requests.length,2);assert.equal(new URL(explicit.requests[1].url).pathname,'/api/v1/artist/42');assert.equal(explicit.requests[1].errorResponse,true);assert.deepEqual(JSON.parse(explicit.requests[1].body),{limit:50,offset:0,total:true});}
for(const firstArtist of [undefined,null,{id:42},{id:42,followed:null},{id:41,followed:true},{id:42,followed:'false'}])for(const followed of [true,false]){const fallback=drive('collection.saved',{type:'artist',id:'42'},[profile,{code:200,artist:firstArtist},{code:200,artist:{id:42,followed}}]);assert.equal(fallback.result.result,followed);assert.equal(fallback.requests.length,3);assert.equal(new URL(fallback.requests[2].url).pathname,'/api/artist/albums/42');assert.deepEqual(JSON.parse(fallback.requests[2].body),{limit:50,offset:0,total:true});}
for(const [firstArtist,secondArtist]of [[{id:41,followed:true},{id:43,followed:false}],[{id:42},{id:43,followed:true}],[{id:42,followed:null},{id:42,followed:null}],[null,null]])assert.equal(drive('collection.saved',{type:'artist',id:'42'},[profile,{code:200,artist:firstArtist},{code:200,artist:secondArtist}]).result.error,'INVALID_RESPONSE');
assert.equal(value('collection.saved',{type:'artist',id:'42'},[profile,{code:500},{code:200,artist:{id:42,followed:true}}]),true);assert.equal(drive('collection.saved',{type:'artist',id:'42'},[profile,{code:500},{code:500}]).result.error,'UNAVAILABLE');
let networkFallback=clone(plugin['collection.saved']({type:'artist',id:'42'},clone(signed)));networkFallback=clone(plugin.onResponse('collection.saved',{status:200,body:JSON.stringify(profile)},networkFallback.state,clone(signed)));networkFallback=clone(plugin.onResponse('collection.saved',{status:0,body:'',error:'NETWORK'},networkFallback.state,clone(signed)));assert.equal(new URL(networkFallback.request.url).pathname,'/api/artist/albums/42');networkFallback=clone(plugin.onResponse('collection.saved',{status:200,body:'{"code":200,"artist":{"id":42,"followed":false}}'},networkFallback.state,clone(signed)));assert.equal(networkFallback.result,false);
for(const subscribed of [true,false]){assert.equal(value('collection.saved',{type:'playlist',id:'10'},[profile,{code:200,playlist:{...playlist(),subscribed}}]),subscribed);assert.equal(value('collection.saved',{type:'album',id:'9'},[profile,{code:200,isSub:subscribed,subscribed:!subscribed}]),subscribed);}
for(const body of [{code:200},{code:200,playlist:null},{code:200,playlist:{...playlist(),subscribed:null}},{code:200,playlist:{...playlist(11),subscribed:true}},{code:200,playlist:playlist()}])assert.equal(drive('collection.saved',{type:'playlist',id:'10'},[profile,body]).result.error,'INVALID_RESPONSE');for(const body of [{code:200},{code:200,isSub:null},{code:200,isSub:'false',subscribed:true}])assert.equal(drive('collection.saved',{type:'album',id:'9'},[profile,body]).result.error,'INVALID_RESPONSE');
for(const specialType of [0,5])assert.equal(drive('collection.save',{type:'playlist',id:'10',saved:true},[profile,{code:200,playlist:playlist(10,7,specialType)}]).result.error,'UNSUPPORTED');for(const value of [playlist(11,8),{...playlist(10,8),creator:null}])assert.equal(drive('collection.save',{type:'playlist',id:'10',saved:true},[profile,{code:200,playlist:value}]).result.error,'INVALID_RESPONSE');
